def _dissection(cells):
    """Order interiors before their planar separator to limit 3D fill."""
    axis = int(np.argmax(cells.shape))
    if cells.shape[axis] <= 3:
        return cells.ravel()
    planes = np.moveaxis(cells, axis, 0)
    middle = len(planes) // 2
    return np.concatenate((_dissection(planes[:middle]), _dissection(planes[middle + 1:]), _dissection(planes[middle:middle + 1])))

def _factor(a, permutation):
    from scipy.sparse.linalg import splu
    return splu(a[permutation, :][:, permutation].tocsc(), permc_spec='NATURAL', diag_pivot_thresh=0, options={'SymmetricMode': True})

def cg(a, rhs, x0=None, M=None, rtol=1e-10, maxiter=100, callback=None):
    x = np.zeros_like(rhs) if x0 is None else x0.copy()
    r = rhs - a @ x
    target = rtol ** 2 * _dot(rhs, rhs)
    previous = None
    for i in range(maxiter):
        if _dot(r, r) <= target:
            return (x, 0)
        z = M(r)
        rz = _dot(r, z)
        if previous is None:
            direction = z
        else:
            direction *= rz / previous
            direction += z
        product = a @ direction
        step = rz / _dot(direction, product)
        x += step * direction
        r -= step * product
        previous = rz
        if callback is not None:
            callback(x)
    return (x, maxiter)
